function prevPermOpt1(arr) {
  // Try every swap and keep the largest result that is still smaller than arr.
  const less = (a, b) => {
    for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return a[k] < b[k];
    return false;
  };
  let best = null;
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      const candidate = arr.slice();
      candidate[i] = arr[j];
      candidate[j] = arr[i];
      if (less(candidate, arr) && (best === null || less(best, candidate))) best = candidate;
    }
  }
  return best === null ? arr.slice() : best;
}

