function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 7);
  const top = large ? (rand() < 0.5 ? 10000 : 50) : (rand() < 0.7 ? 4 : 10000);
  const arr = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const shape = rand();
  // Sorted arrays have no smaller swap; nearly sorted ones put the only descent at a random spot.
  if (shape < 0.5) {
    arr.sort((a, b) => a - b);
    if (shape < 0.4 && n > 1) {
      const k = Math.floor(rand() * n);
      const value = 1 + Math.floor(rand() * top);
      arr[k] = value;
    }
  }
  return [arr];
}
